create table prospect_qualifications(id uuid primary key default gen_random_uuid(),prospect_organisation_id uuid not null unique references prospect_organisations(id) on delete cascade,score int not null check(score between 0 and 100),computed_category text not null,effective_category text not null,methodology_version text not null,factors jsonb not null,missing_information text[] not null default '{}',override_reason text,overridden_by uuid references internal_users(id),assessed_at timestamptz not null);
create table sales_opportunities(id uuid primary key default gen_random_uuid(),prospect_organisation_id uuid not null unique references prospect_organisations(id) on delete restrict,stage text not null check(stage in('discovered','researched','qualified','contacted','engaged','demo','evaluating','proposal','won','lost','nurture')),owner_id uuid references internal_users(id),next_action text,last_interaction_at timestamptz,expected_value numeric,probability int check(probability between 0 and 100),close_target date,lost_reason text,lost_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(stage<>'lost' or lost_reason is not null));
create table internal_tasks(id uuid primary key default gen_random_uuid(),title text not null,description text,owner_id uuid references internal_users(id),due_at timestamptz,priority text not null check(priority in('low','medium','high','urgent')),status text not null check(status in('open','in_progress','completed','cancelled')),source text not null check(source in('manual','system','intelligence')),related_type text not null check(related_type in('prospect','customer','opportunity','onboarding','support','product','system')),related_id text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table prospect_qualifications enable row level security;alter table sales_opportunities enable row level security;alter table internal_tasks enable row level security;
grant select,insert,update on prospect_qualifications,sales_opportunities,internal_tasks to authenticated;
create policy qualification_select on prospect_qualifications for select using(is_active_internal_user());create policy qualification_write on prospect_qualifications for all using(internal_has_role(array['super_admin','operations','sales']::internal_role[])) with check(internal_has_role(array['super_admin','operations','sales']::internal_role[]));
create policy sales_select on sales_opportunities for select using(is_active_internal_user());create policy sales_write on sales_opportunities for all using(internal_has_role(array['super_admin','operations','sales','customer_success']::internal_role[])) with check(internal_has_role(array['super_admin','operations','sales','customer_success']::internal_role[]));
create policy tasks_select on internal_tasks for select using(is_active_internal_user());create policy tasks_write on internal_tasks for all using(internal_has_role(array['super_admin','operations','sales','customer_success','support','product']::internal_role[])) with check(internal_has_role(array['super_admin','operations','sales','customer_success','support','product']::internal_role[]));
